// M1: types.ts shape tests. Fixture is synthetic and built in-test (no file reads).

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { POS_VALUES, type Column, type Entry, type SourceImage, type Word } from "../src/types.ts";

describe("types", () => {
  it("holds a full synthetic Entry fixture", () => {
    const sourceImage: SourceImage = {
      page_number: 5,
      column: "left",
      bbox: [118, 226, 420, 31],
    };
    const word: Word = {
      text: "abandon",
      bbox: [118, 226, 72, 31],
      languageCode: "en",
      confidence: 0.97,
    };
    const entry: Entry = {
      entry_id: "p05-l-0001",
      headword_en: "abandon",
      headword_normalized: "abandon",
      pronunciation: "əˈbændən",
      pos: "v",
      translation_fa: "ترک کردن",
      definition_en: "To give up a right or claim voluntarily.",
      raw_ocr_snippet: "abandon əˈbændən v. ترک کردن",
      source_image: sourceImage,
      is_continuation: false,
      needs_review: false,
      confidence: 0.96,
    };

    // Field set is exactly the contract's (contract §4); fixtures type-check only
    // if types.ts declares them, so assert the runtime shape too.
    assert.deepEqual(Object.keys(entry), [
      "entry_id",
      "headword_en",
      "headword_normalized",
      "pronunciation",
      "pos",
      "translation_fa",
      "definition_en",
      "raw_ocr_snippet",
      "source_image",
      "is_continuation",
      "needs_review",
      "confidence",
    ]);
    assert.deepEqual(Object.keys(sourceImage), ["page_number", "column", "bbox"]);
    assert.deepEqual(Object.keys(word), ["text", "bbox", "languageCode", "confidence"]);
    assert.equal(entry.source_image.column, "left");
    const col: Column = "right";
    assert.equal(col, "right");
  });

  it("POS_VALUES is the placeholder set from the source", () => {
    assert.deepEqual(POS_VALUES, ["n", "v", "adj", "adv", "prep", "conj", "phr"]);
  });
});

// Entry shape per docs 10. Direction is English headword -> Farsi equivalent ->
// English definition (correcting NOTES.md's "Farsi_Term" mislabel).

export type Column = "left" | "right";

export interface SourceImage {
  page_number: number;
  column: Column;
  /** union of the entry's Vision word bounding boxes: [x, y, w, h] */
  bbox: [number, number, number, number];
}

export interface Entry {
  entry_id: string;
  headword_en: string;
  /** lowercased/stripped, for exact + prefix search */
  headword_normalized: string;
  pronunciation: string | null;
  pos: string | null;
  /** Arabic-script, Unicode-normalized (NFC + Arabic->Persian) */
  translation_fa: string;
  definition_en: string | null;
  /** pre-correction Vision text, for audit */
  raw_ocr_snippet: string;
  source_image: SourceImage;
  /** true if this entry runs over from a prior page */
  is_continuation: boolean;
  /** set by validation */
  needs_review: boolean;
  /** min/avg of the entry's Vision word confidences */
  confidence: number | null;
}

/** Internal normalized word. Built from raw Vision JSON by the parser.
 *  languageCode is a WEAK hint only (Vision mis-tags English) -- separation is by
 *  script + column, not this field (docs 2, docs 9).
 *  Divergence D2: lives in types.ts (source: parser/columns.ts) per the DoD;
 *  columns.ts re-exports it. Field names identical. */
export interface Word {
  /** reconstructed by concatenating symbols[].text (no word-level text field exists) */
  text: string;
  /** [x, y, w, h] in pixels, from boundingBox.vertices (normalizedVertices is empty) */
  bbox: [number, number, number, number];
  languageCode: string | null;
  confidence: number | null;
}

// TODO [verify]: the real POS abbreviation set must be derived from the actual
// dictionary's front-matter key, NOT invented here. These are placeholders so the
// Tier-1 enum has something to check; replace once the corpus is sampled (docs 13.5).
export const POS_VALUES = ["n", "v", "adj", "adv", "prep", "conj", "phr"] as const;
export type Pos = (typeof POS_VALUES)[number];

// M2: script.ts detection tests. All strings are synthetic, built in-test.

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { hasArabicScript, hasLatinLetters, isFarsiOnly, isLatinOnly } from "../src/script.ts";

describe("script detection", () => {
  it("hasArabicScript / hasLatinLetters", () => {
    assert.equal(hasArabicScript("ترک"), true);
    assert.equal(hasArabicScript("abandon"), false);
    // Persian-specific letters پ چ ژ گ ک ی fall inside the Arabic block
    assert.equal(hasArabicScript("پ چ ژ گ ک ی"), true);
    // Arabic-Indic digits ۰-۹ share the block
    assert.equal(hasArabicScript("۱۲۳۴"), true);
    assert.equal(hasArabicScript(""), false);
    assert.equal(hasArabicScript("1234"), false);

    assert.equal(hasLatinLetters("abandon"), true);
    assert.equal(hasLatinLetters("AbC"), true);
    assert.equal(hasLatinLetters("ترک"), false);
    assert.equal(hasLatinLetters("1234"), false);
    assert.equal(hasLatinLetters(""), false);
    assert.equal(hasLatinLetters("۱۲۳۴"), false);
  });

  it("pure Farsi: Arabic script present, no Latin letters", () => {
    assert.equal(isFarsiOnly("ترک کردن"), true);
    assert.equal(isFarsiOnly("پ چ ژ گ ک ی"), true);
  });

  it("pure Latin: Latin letters present, no Arabic script", () => {
    assert.equal(isLatinOnly("abandon"), true);
    assert.equal(isLatinOnly("mixed? no."), true);
  });

  it("mixed: both scripts present", () => {
    const mixed = "abandon ترک";
    assert.equal(isFarsiOnly(mixed), false);
    assert.equal(isLatinOnly(mixed), false);
  });

  it("digit-only and empty strings are neither", () => {
    assert.equal(isFarsiOnly("1234"), false);
    assert.equal(isLatinOnly("1234"), false);
    assert.equal(isFarsiOnly(""), false);
    assert.equal(isLatinOnly(""), false);
    // Arabic-Indic digits have no Latin letters -> Farsi side
    assert.equal(isFarsiOnly("۱۲۳۴"), true);
    assert.equal(isLatinOnly("۱۲۳۴"), false);
  });
});

// Shared script detection. Used by BOTH the parser (separate Farsi from the
// English side, docs 5 step 3) and validation Tier-2 script isolation (docs 9).
// Ranges are taken verbatim from docs 9, not from memory.

// Arabic block covers U+0600-U+06FF; the Persian-specific letters the guide calls
// out (پ چ ژ گ ک ی) already fall inside that block, so the range is sufficient.
const ARABIC_BLOCK = /[\u0600-\u06FF]/;
const LATIN_LETTER = /[A-Za-z]/;

export function hasArabicScript(s: string): boolean {
  return ARABIC_BLOCK.test(s);
}

export function hasLatinLetters(s: string): boolean {
  return LATIN_LETTER.test(s);
}

/** Farsi side: contains Arabic-block script and NO Latin letters. */
export function isFarsiOnly(s: string): boolean {
  return hasArabicScript(s) && !hasLatinLetters(s);
}

/** English side: contains Latin letters and NO Arabic-block script. */
export function isLatinOnly(s: string): boolean {
  return hasLatinLetters(s) && !hasArabicScript(s);
}

// M3: parser/columns.ts tests. All fixtures synthetic, built in-test.

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import {
  FALLBACK_COLUMN_SPLIT_X,
  type Word,
  assignColumn,
  bboxFromVertices,
  detectColumnSplitX,
  splitColumns,
  unionBbox,
} from "../src/parser/columns.ts";

const mkWord = (x: number, y = 0, w = 50, h = 20, text = "w"): Word => ({
  text,
  bbox: [x, y, w, h],
  languageCode: "en",
  confidence: 0.9,
});

describe("bboxFromVertices", () => {
  it("returns [0,0,0,0] for undefined or empty vertices", () => {
    assert.deepEqual(bboxFromVertices(undefined), [0, 0, 0, 0]);
    assert.deepEqual(bboxFromVertices([]), [0, 0, 0, 0]);
  });

  it("takes min/max over near-axis-aligned vertices", () => {
    // a skewed box: x 118..190, y 226..257
    const box = bboxFromVertices([
      { x: 118, y: 226 },
      { x: 190, y: 228 },
      { x: 188, y: 257 },
      { x: 120, y: 255 },
    ]);
    assert.deepEqual(box, [118, 226, 72, 31]);
  });

  it("treats missing coordinates as 0", () => {
    assert.deepEqual(bboxFromVertices([{ x: 10 }, { x: 30, y: 40 }]), [10, 0, 20, 40]);
  });
});

describe("unionBbox", () => {
  it("returns [0,0,0,0] for an empty array", () => {
    assert.deepEqual(unionBbox([]), [0, 0, 0, 0]);
  });

  it("unions boxes into the enclosing box", () => {
    assert.deepEqual(
      unionBbox([
        [100, 200, 50, 20],
        [300, 205, 60, 20],
      ]),
      [100, 200, 260, 25],
    );
  });
});

describe("detectColumnSplitX", () => {
  it("finds a clear central gutter at the gap midpoint", () => {
    // left col x={100,200,300}, right col x={800,900}; gap 300->800 mid 550
    const words = [100, 200, 300, 800, 900].map((x) => mkWord(x));
    assert.equal(detectColumnSplitX(words), 550);
  });

  it("ignores wide margin gaps outside the central band", () => {
    // margin gaps 100->580 (mid 340) and 1020->1500 (mid 1260) are both wider
    // than the gutter 600->1000 (400), but fall outside the central band
    // [380, 1220]; the gutter wins.
    const words = [100, 580, 600, 1000, 1020, 1500].map((x) => mkWord(x));
    assert.equal(detectColumnSplitX(words), 800);
  });

  it("falls back when all words share the same left-edge (range 0)", () => {
    const words = [500, 500, 500].map((x) => mkWord(x));
    assert.equal(detectColumnSplitX(words), FALLBACK_COLUMN_SPLIT_X);
  });

  it("falls back for fewer than 2 words", () => {
    assert.equal(detectColumnSplitX([mkWord(100)]), FALLBACK_COLUMN_SPLIT_X);
    assert.equal(detectColumnSplitX([]), FALLBACK_COLUMN_SPLIT_X);
  });

  it("falls back when the best central gap is below minGap", () => {
    // gutter gap 400 at mid 800, but minGap 500 rejects it
    const words = [100, 580, 600, 1000, 1020, 1500].map((x) => mkWord(x));
    assert.equal(detectColumnSplitX(words, 500), FALLBACK_COLUMN_SPLIT_X);
  });
});

describe("assignColumn", () => {
  it("splits at the boundary: left when x < splitX, right otherwise", () => {
    assert.equal(assignColumn(mkWord(799), 800), "left");
    assert.equal(assignColumn(mkWord(800), 800), "right");
    assert.equal(assignColumn(mkWord(801), 800), "right");
  });
});

describe("splitColumns", () => {
  it("buckets words into left/right columns", () => {
    const words = [100, 200, 900, 1000].map((x) => mkWord(x));
    const { left, right } = splitColumns(words, 550);
    assert.deepEqual(left.map((w) => w.bbox[0]), [100, 200]);
    assert.deepEqual(right.map((w) => w.bbox[0]), [900, 1000]);
  });

  it("defaults splitX to the detected gutter", () => {
    const words = [100, 200, 300, 800, 900].map((x) => mkWord(x));
    const { left, right } = splitColumns(words);
    assert.deepEqual(left.map((w) => w.bbox[0]), [100, 200, 300]);
    assert.deepEqual(right.map((w) => w.bbox[0]), [800, 900]);
  });
});

// Deterministic column + geometry logic (docs 5 steps 1-2). Implementable straight
// from the guide's coordinates + the verified Vision shape; no LLM. Blocks are
// ignored entirely -- we reconstruct from words + coordinates.
import type { Column, Word } from "../types.ts";

// Divergence D2: Word lives in types.ts (source: here) so types.ts exports the
// shape the DoD requires; re-exported below for the source's import sites.
export type { Word };

export interface Vertex {
  x?: number;
  y?: number;
}

/** Vision gives 4 (near-axis-aligned) vertices; take min/max for a robust box. */
export function bboxFromVertices(
  vertices: Vertex[] | undefined,
): [number, number, number, number] {
  if (!vertices || vertices.length === 0) return [0, 0, 0, 0];
  const xs = vertices.map((v) => v.x ?? 0);
  const ys = vertices.map((v) => v.y ?? 0);
  const x = Math.min(...xs);
  const y = Math.min(...ys);
  return [x, y, Math.max(...xs) - x, Math.max(...ys) - y];
}

export function unionBbox(
  boxes: Array<[number, number, number, number]>,
): [number, number, number, number] {
  if (boxes.length === 0) return [0, 0, 0, 0];
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const [x, y, w, h] of boxes) {
    minX = Math.min(minX, x);
    minY = Math.min(minY, y);
    maxX = Math.max(maxX, x + w);
    maxY = Math.max(maxY, y + h);
  }
  return [minX, minY, maxX - minX, maxY - minY];
}

// Fallback only. The column gutter is detected PER PAGE (see detectColumnSplitX):
// pages are not consistently aligned -- e.g. page 07 is shifted ~120px vs 05/06, so
// a single hardcoded split miscategorizes a whole column. This value is used only
// when dynamic detection can't find a confident gap.
export const FALLBACK_COLUMN_SPLIT_X = 1100;

const leftEdge = (w: Word): number => w.bbox[0];

/** Detect the two-column gutter for one page: the largest gap between consecutive
 *  word left-edges whose midpoint falls in the central band of the page's x-range.
 *  Central-band constraint avoids picking a wide margin gap; robust to per-page
 *  horizontal shift. Falls back to FALLBACK_COLUMN_SPLIT_X if no confident gap. */
export function detectColumnSplitX(words: Word[], minGap = 20): number {
  if (words.length < 2) return FALLBACK_COLUMN_SPLIT_X;
  const xs = words.map(leftEdge).sort((a, b) => a - b);
  const xmin = xs[0] ?? 0;
  const xmax = xs[xs.length - 1] ?? 0;
  const range = xmax - xmin;
  if (range <= 0) return FALLBACK_COLUMN_SPLIT_X;
  const lo = xmin + 0.2 * range;
  const hi = xmax - 0.2 * range;
  let bestGap = 0;
  let bestSplit = FALLBACK_COLUMN_SPLIT_X;
  for (let i = 1; i < xs.length; i++) {
    const a = xs[i - 1] ?? 0;
    const b = xs[i] ?? 0;
    const gap = b - a;
    const mid = (a + b) / 2;
    if (gap > bestGap && mid >= lo && mid <= hi) {
      bestGap = gap;
      bestSplit = mid;
    }
  }
  return bestGap >= minGap ? bestSplit : FALLBACK_COLUMN_SPLIT_X;
}

export function assignColumn(word: Word, splitX: number): Column {
  return word.bbox[0] < splitX ? "left" : "right";
}

/** Split words into columns. splitX defaults to the per-page detected gutter. */
export function splitColumns(
  words: Word[],
  splitX: number = detectColumnSplitX(words),
): Record<Column, Word[]> {
  const left: Word[] = [];
  const right: Word[] = [];
  for (const w of words) {
    if (assignColumn(w, splitX) === "left") left.push(w);
    else right.push(w);
  }
  return { left, right };
}

// M4: parser/lines.ts tests. All fixtures synthetic, built in-test.

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { type Word, unionBbox } from "../src/parser/columns.ts";
import { groupIntoLines } from "../src/parser/lines.ts";

const mkWord = (
  x: number,
  y: number,
  text: string,
  w = 50,
  h = 20,
  confidence: number | null = 0.9,
): Word => ({ text, bbox: [x, y, w, h], languageCode: "en", confidence });

describe("groupIntoLines", () => {
  it("splits two vertical clusters into two lines, ordered by yTop", () => {
    // heights 20 -> tol = max(6, 10) = 10; centers 110 vs 210 are far apart
    const words = [
      mkWord(100, 100, "a"), // center 110
      mkWord(200, 100, "b"), // center 110
      mkWord(100, 200, "c"), // center 210
      mkWord(200, 200, "d"), // center 210
    ];
    const lines = groupIntoLines(words);
    assert.equal(lines.length, 2);
    assert.deepEqual(
      lines.map((l) => l.text),
      ["a b", "c d"],
    );
    assert.deepEqual(
      lines.map((l) => l.yTop),
      [100, 200],
    );
  });

  it("merges words within the same-line tolerance (one cluster, drift allowed)", () => {
    // centers 110, 115 -> within tol 10 -> one line despite the small offset
    const words = [mkWord(100, 100, "a"), mkWord(200, 105, "b")];
    const lines = groupIntoLines(words);
    assert.equal(lines.length, 1);
    assert.equal(lines[0]?.text, "a b");
  });

  it("separates words beyond the tolerance", () => {
    // centers 110 vs 135 -> 25 > tol 10 -> two lines
    const words = [mkWord(100, 100, "a"), mkWord(200, 125, "b")];
    const lines = groupIntoLines(words);
    assert.equal(lines.length, 2);
    assert.deepEqual(
      lines.map((l) => l.text),
      ["a", "b"],
    );
  });

  it("orders pure-Farsi lines RTL (x-descending) and tags them farsi", () => {
    const words = [
      mkWord(300, 100, "ترک", 50, 20), // visually rightmost word comes first
      mkWord(100, 100, "کردن", 60, 20),
    ];
    const lines = groupIntoLines(words);
    assert.equal(lines.length, 1);
    const line = lines[0];
    assert.equal(line?.script, "farsi");
    assert.equal(line?.text, "ترک کردن");
    assert.deepEqual(
      line?.words.map((w) => w.text),
      ["ترک", "کردن"],
    );
    // line bbox = union of member word boxes
    assert.deepEqual(line?.bbox, unionBbox(words.map((w) => w.bbox)));
  });

  it("tags mixed lines mixed and orders them LTR", () => {
    const words = [
      mkWord(300, 100, "ترک"),
      mkWord(100, 100, "abandon"),
    ];
    const lines = groupIntoLines(words);
    assert.equal(lines.length, 1);
    const line = lines[0];
    assert.equal(line?.script, "mixed");
    assert.equal(line?.text, "abandon ترک");
    assert.deepEqual(
      line?.words.map((w) => w.text),
      ["abandon", "ترک"],
    );
  });

  it("returns avgConfidence null when no word has a numeric confidence", () => {
    const words = [mkWord(100, 100, "a", 50, 20, null), mkWord(200, 100, "b", 50, 20, null)];
    const lines = groupIntoLines(words);
    assert.equal(lines.length, 1);
    assert.equal(lines[0]?.avgConfidence, null);
  });

  it("averages only the numeric confidences when some are null", () => {
    const words = [mkWord(100, 100, "a", 50, 20, 0.8), mkWord(200, 100, "b", 50, 20, null)];
    const lines = groupIntoLines(words);
    assert.equal(lines[0]?.avgConfidence, 0.8);
  });

  it("returns [] for an empty column", () => {
    assert.deepEqual(groupIntoLines([]), []);
  });
});

// Line grouping (docs 5 step 3, deterministic half). Words within a column are
// clustered into lines by vertical proximity, ordered within a line by X, and
// script-tagged. This reading-ordered, script-tagged transcript is what the LLM
// consumes to segment entries and slot fields -- the LLM does the "residue"
// (headword vs runover vs cross-ref vs example), not this code (docs 3).
import type { Column } from "../types.ts";
import { isFarsiOnly, isLatinOnly } from "../script.ts";
import { type Word, unionBbox } from "./columns.ts";

export type LineScript = "latin" | "farsi" | "mixed" | "other";

export interface Line {
  /** words joined by a space, in reading order (RTL for pure-Farsi lines) */
  text: string;
  script: LineScript;
  yTop: number;
  bbox: [number, number, number, number];
  avgConfidence: number | null;
  words: Word[];
}

export interface ColumnTranscript {
  page_number: number;
  column: Column;
  lines: Line[];
}

const yCenter = (w: Word): number => w.bbox[1] + w.bbox[3] / 2;
const height = (w: Word): number => w.bbox[3];
const minX = (w: Word): number => w.bbox[0];

function median(values: number[]): number {
  if (values.length === 0) return 0;
  const s = [...values].sort((a, b) => a - b);
  return s[Math.floor(s.length / 2)] ?? 0;
}

function classifyScript(words: Word[]): LineScript {
  let latin = 0;
  let farsi = 0;
  for (const w of words) {
    if (isFarsiOnly(w.text)) farsi++;
    else if (isLatinOnly(w.text)) latin++;
  }
  if (farsi > 0 && latin > 0) return "mixed";
  if (farsi > 0) return "farsi";
  if (latin > 0) return "latin";
  return "other";
}

function makeLine(words: Word[]): Line {
  const script = classifyScript(words);
  // Pure-Farsi lines read right-to-left; everything else left-to-right.
  const ordered = [...words].sort((a, b) =>
    script === "farsi" ? minX(b) - minX(a) : minX(a) - minX(b),
  );
  const confidences = ordered
    .map((w) => w.confidence)
    .filter((c): c is number => typeof c === "number");
  const avgConfidence =
    confidences.length > 0
      ? confidences.reduce((s, c) => s + c, 0) / confidences.length
      : null;
  const bbox = unionBbox(ordered.map((w) => w.bbox));
  return {
    text: ordered.map((w) => w.text).join(" "),
    script,
    yTop: bbox[1],
    bbox,
    avgConfidence,
    words: ordered,
  };
}

/** Cluster a single column's words into lines by Y proximity, then order by yTop. */
export function groupIntoLines(words: Word[]): Line[] {
  if (words.length === 0) return [];
  const sorted = [...words].sort((a, b) => yCenter(a) - yCenter(b));
  const tol = Math.max(6, median(sorted.map(height)) * 0.5);

  const groups: Word[][] = [];
  let current: Word[] = [];
  let currentY = Number.NaN;
  for (const w of sorted) {
    const y = yCenter(w);
    if (current.length === 0 || Math.abs(y - currentY) <= tol) {
      current.push(w);
      currentY = current.reduce((s, x) => s + yCenter(x), 0) / current.length;
    } else {
      groups.push(current);
      current = [w];
      currentY = y;
    }
  }
  if (current.length > 0) groups.push(current);

  return groups.map(makeLine).sort((a, b) => a.yTop - b.yTop);
}

