mkdir -p /tmp/xc1 && cat > /tmp/xc1/diff.ts <<'EOF'
import * as sCol from "/Users/afshin/Documents/dev/law-dictionary-ocr/old-second/src/parser/columns.ts";
import * as sLines from "/Users/afshin/Documents/dev/law-dictionary-ocr/old-second/src/parser/lines.ts";
import * as pCol from "/Users/afshin/Documents/dev/law-dictionary-ocr/src/parser/columns.ts";
import * as pLines from "/Users/afshin/Documents/dev/law-dictionary-ocr/src/parser/lines.ts";

type W = { text: string; bbox: [number, number, number, number]; languageCode: string | null; confidence: number | null };

let seed = 42;
const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648);
const pick = <T,>(a: T[]): T => a[Math.floor(rnd() * a.length)]!;

const texts = ["abandon", "ترک", "کردن", "1234", "۱۲۳", "...", "", "abandon ترک", "xyz", "پ"];
const gen = (): W => ({
  text: pick(texts),
  bbox: [
    Math.round(rnd() * 2000),
    Math.round(rnd() * 3000),
    Math.round(rnd() * 120),
    Math.round(rnd() * 40),
  ] as [number, number, number, number],
  languageCode: pick([null, "en", "fa"]),
  confidence: pick([null, 0.5, 0.9, 0.99, 0]),
});

