// M7: validation/cross-record.ts tests. Fixtures built in-test.

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import type { Entry } from "../src/types.ts";
import { checkAlphabeticalContinuity } from "../src/validation/cross-record.ts";

const mkEntry = (headword_normalized: string, is_continuation = false): Entry => ({
  entry_id: `p05-l-${headword_normalized}`,
  headword_en: headword_normalized,
  headword_normalized,
  pronunciation: null,
  pos: null,
  translation_fa: "ترک",
  definition_en: null,
  raw_ocr_snippet: headword_normalized,
  source_image: { page_number: 5, column: "left", bbox: [0, 0, 10, 10] },
  is_continuation,
  needs_review: false,
  confidence: null,
});

describe("checkAlphabeticalContinuity", () => {
  it("returns no violations for ordered entries", () => {
    const entries = ["abandon", "abate", "abet", "abide"].map((h) => mkEntry(h));
    assert.deepEqual(checkAlphabeticalContinuity(entries), []);
  });

  it("flags an out-of-order pair once, with the offending index and both headwords", () => {
    const entries = [mkEntry("abandon"), mkEntry("abide"), mkEntry("abate")];
    assert.deepEqual(checkAlphabeticalContinuity(entries), [
      { index: 2, prev: "abide", curr: "abate" },
    ]);
  });

  it("reports each violation with its own index", () => {
    const entries = ["b", "a", "c", "b"].map((h) => mkEntry(h));
    assert.deepEqual(checkAlphabeticalContinuity(entries), [
      { index: 1, prev: "b", curr: "a" },
      { index: 3, prev: "c", curr: "b" },
    ]);
  });

  it("does not flag equal headwords (strict comparison)", () => {
    const entries = [mkEntry("abandon"), mkEntry("abandon")];
    assert.deepEqual(checkAlphabeticalContinuity(entries), []);
  });

  it("returns an empty array for no entries", () => {
    assert.deepEqual(checkAlphabeticalContinuity([]), []);
    assert.deepEqual(checkAlphabeticalContinuity([mkEntry("abandon")]), []);
  });

  it("skips continuations: alphabetically-wrong continuation is NOT flagged", () => {
    const entries = [mkEntry("abide"), mkEntry("abandon", true), mkEntry("abet")];
    assert.deepEqual(checkAlphabeticalContinuity(entries), []);
  });

  it("skips continuations without breaking the ordering baseline", () => {
    // the continuation's headword must not become `prev` for the next entry
    const entries = [mkEntry("abel"), mkEntry("zzz", true), mkEntry("abet")];
    assert.deepEqual(checkAlphabeticalContinuity(entries), []);
  });

  it("does not mutate the input array", () => {
    const entries = [mkEntry("abide"), mkEntry("abandon")];
    const snapshot = entries.map((e) => e.headword_normalized);
    checkAlphabeticalContinuity(entries);
    assert.deepEqual(
      entries.map((e) => e.headword_normalized),
      snapshot,
    );
  });
});

// Tier-2 domain/semantic validation (docs 9). drizzle-zod gives Tier-1 (structural)
// only; these refinements are the ones "you write". Script isolation is the REAL
// language check here, because Vision mis-tags English as Latin/Italian/French so
// languageCode cannot be trusted.
import { z } from "zod";
import { hasLatinLetters, isFarsiOnly, isLatinOnly } from "../script.ts";

/** translation_fa must be Arabic-script with no Latin letters (catches the most
 *  common column-swap error: a Latin word landing in the Farsi field). */
export const farsiFieldSchema = z.string().refine((v) => isFarsiOnly(v), {
  message: "translation_fa must be Arabic-script with no Latin letters",
});

/** headword_en must be Latin-only. */
export const englishHeadwordSchema = z.string().refine((v) => isLatinOnly(v), {
  message: "headword_en must be Latin-only",
});

/** Diacritic / dot sanity: suspiciously short Farsi strings are borderline, not
 *  auto-rejects -> caller should route these to needs_review (docs 9). */
export function looksSuspiciousFa(v: string): boolean {
  const stripped = v.replace(/\s/g, "");
  return stripped.length <= 2 || hasLatinLetters(v);
}

// Tier-1 structural validation (docs 9, D4). Replaces old-second/src/db/schema.ts:
// v3 has no database, so the drizzle table + drizzle-zod generator collapse into this
// hand-written schema. Column clauses mirror the dropped table's insert-schema
// semantics: notNull -> required non-nullable; notNull+default -> optional;
// no notNull -> optional + nullable. Keys are the contract's snake_case (§4).
import { z } from "zod";
import type { SourceImage } from "../types.ts";

// Typed against the contract shape so field/type drift from types.ts fails to compile.
// Stricter than the dropped jsonb column, which drizzle-zod typed as `unknown`.
const sourceImageSchema: z.ZodType<SourceImage> = z.object({
  page_number: z.number(),
  column: z.enum(["left", "right"]),
  bbox: z.tuple([z.number(), z.number(), z.number(), z.number()]),
});

// pos stays a plain string: the source table's `text("pos")` was never enum-checked,
// and the real POS set is [verify] (D9).
export const insertEntrySchema = z.object({
  entry_id: z.string(),
  headword_en: z.string(),
  headword_normalized: z.string(),
  pronunciation: z.string().optional().nullable(),
  pos: z.string().optional().nullable(),
  translation_fa: z.string(),
  definition_en: z.string().optional().nullable(),
  raw_ocr_snippet: z.string(),
  source_image: sourceImageSchema,
  is_continuation: z.boolean().optional(),
  needs_review: z.boolean().optional(),
  confidence: z.number().optional().nullable(),
});

// Cross-record invariants run OUTSIDE Zod (Zod validates one record at a time,
// docs 9). The key check is alphabetical-order continuity across the corpus
// (docs 6), which MUST tolerate runover continuations.
import type { Entry } from "../types.ts";

export interface OrderViolation {
  index: number;
  prev: string;
  curr: string;
}

/** Flags entries whose normalized headword sorts before the previous one.
 *  Continuations (is_continuation) are skipped: an entry spilling from the prior
 *  page is not an ordering violation. */
export function checkAlphabeticalContinuity(entries: Entry[]): OrderViolation[] {
  const violations: OrderViolation[] = [];
  let prev: string | null = null;
  for (let i = 0; i < entries.length; i++) {
    const e = entries[i];
    if (e === undefined || e.is_continuation) continue;
    if (prev !== null && e.headword_normalized < prev) {
      violations.push({ index: i, prev, curr: e.headword_normalized });
    }
    prev = e.headword_normalized;
  }
  return violations;
}

