  // "aardvark" sorts before "abandon"; without the skip it would be a violation
  const entries = [mkEntry("abandon"), mkEntry("aardvark", true), mkEntry("abate")];
  assert.deepEqual(checkAlphabeticalContinuity(entries), []);
});

