// Tier-1 equivalence probe: source drizzle-zod insert schema vs ported zod schema.
// Compares per-column acceptance decisions on a value battery, and whole-record decisions
// (source keys are camelCase; the port keys on the contract's snake_case).
import { boolean, jsonb, pgTable, real, text } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { insertEntrySchema as port } from "/Users/afshin/Documents/dev/law-dictionary-ocr/src/validation/entry-schema.ts";

const entries = pgTable("entries", {
  entryId: text("entry_id").primaryKey(),
  headwordEn: text("headword_en").notNull(),
  headwordNormalized: text("headword_normalized").notNull(),
  pronunciation: text("pronunciation"),
  pos: text("pos"),
  translationFa: text("translation_fa").notNull(),
  definitionEn: text("definition_en"),
  rawOcrSnippet: text("raw_ocr_snippet").notNull(),
  sourceImage: jsonb("source_image").notNull(),
  isContinuation: boolean("is_continuation").notNull().default(false),
  needsReview: boolean("needs_review").notNull().default(false),
  confidence: real("confidence"),
});
const src = createInsertSchema(entries) as any;

const camelToSnake = (k: string) => k.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`);

const strings = ["abandon", "", "  ", "ترک کردن", "1234", 42, null, undefined, {}, true, [1]];
const bools = [true, false, null, undefined, 0, "false"];
const numbers = [0, 0.96, -1, null, undefined, "0.9", Number.NaN];
const images: unknown[] = [
  { page_number: 5, column: "left", bbox: [1, 2, 3, 4] },
  { page_number: 5, column: "middle", bbox: [1, 2, 3, 4] },
  { page_number: 5, column: "left", bbox: [1, 2, 3] },
  { page_number: "5", column: "left", bbox: [1, 2, 3, 4] },
  {}, null, "garbage", [1, 2], [{ foo: 1 }], true,
];
const batteries: Record<string, unknown[]> = {
  entry_id: strings, headword_en: strings, headword_normalized: strings,
  translation_fa: strings, raw_ocr_snippet: strings,
  pronunciation: strings, pos: strings, definition_en: strings,
  is_continuation: bools, needs_review: bools, confidence: numbers,
  source_image: images,
};

let same = 0;
const diffs: string[] = [];
for (const [snake, values] of Object.entries(batteries)) {
  const camel = snake.replace(/_([a-z])/g, (_, c) => c.toUpperCase());
  const srcField = src.shape[camel];
  const portField = (port as any).shape[snake];
  for (const v of values) {
    const a = srcField.safeParse(v).success;
    const b = portField.safeParse(v).success;
    const label = `${snake}=${JSON.stringify(v) ?? String(v)}`;
    if (a === b) same++;
    else diffs.push(`${label}: source=${a} port=${b}`);
  }
}
console.log(`per-column: ${same} identical decisions, ${diffs.length} divergent`);
for (const d of diffs) console.log("  DIVERGENT", d);

// whole-record decisions, source in camelCase, port in snake_case
const rec = (o: Record<string, unknown>) => o;
const base = {
  entry_id: "p05-l-0001", headword_en: "abandon", headword_normalized: "abandon",
  pronunciation: null, pos: null, translation_fa: "ترک کردن", definition_en: null,
  raw_ocr_snippet: "x", source_image: { page_number: 5, column: "left", bbox: [1, 2, 3, 4] },
  is_continuation: false, needs_review: false, confidence: 0.9,
};
const toCamel = (o: Record<string, unknown>) =>
  Object.fromEntries(Object.entries(o).map(([k, v]) => [camelToSnake(k) === k ? k.replace(/_([a-z])/g, (_, c) => c.toUpperCase()) : k, v]));
const cases: Array<[string, Record<string, unknown>]> = [
  ["full", base],
  ["null optionals", { ...base, pronunciation: null, pos: null, definition_en: null, confidence: null }],
  ["omitted optionals", rec({ entry_id: "a", headword_en: "b", headword_normalized: "b", translation_fa: "c", raw_ocr_snippet: "d", source_image: { page_number: 5, column: "right", bbox: [0, 0, 1, 1] } })],
  ["missing entry_id", Object.fromEntries(Object.entries(base).filter(([k]) => k !== "entry_id"))],
  ["missing translation_fa", Object.fromEntries(Object.entries(base).filter(([k]) => k !== "translation_fa"))],
  ["extra key", { ...base, extra_key: "z" }],
  ["pos garbage", { ...base, pos: "not-a-pos" }],
  ["bad source_image column", { ...base, source_image: { page_number: 5, column: "middle", bbox: [1, 2, 3, 4] } }],
  ["bad source_image arity", { ...base, source_image: { page_number: 5, column: "left", bbox: [1, 2, 3] } }],
];
let sameRec = 0;
